(() => {
'use strict';
const $=s=>document.querySelector(s), KEY='toeic700.studio.v1';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',reading:'<path d="M12 6c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Z"/><path d="M12 6v15"/>',listening:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>',vocabulary:'<rect x="5" y="5" width="15" height="16" rx="3"/><path d="M16 2H5a3 3 0 0 0-3 3v11M9 15l3-6 3 6m-5-2h4"/>',review:'<path d="M4 7v5h5M4 12a8 8 0 1 0 2-6"/>',stats:'<path d="M4 20V10m8 10V4m8 16v-7"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m9 5 11 7-11 7Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',flag:'<path d="M5 21V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',leaf:'<path d="M20 3C6 2 1 10 7 17S23 14 20 3ZM5 21l10-11"/>',exam:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h3"/>',pen:'<path d="M4 20h4L19 9l-4-4L4 16v4ZM14 6l4 4"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const shiftDay=(key,n)=>{const d=new Date(key+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+n);return dateKey(d)};
const daysBetween=(a,b)=>Math.round((new Date(b+'T12:00:00+08:00')-new Date(a+'T12:00:00+08:00'))/86400000);
const isDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v);

/* ---------- 題型定義 ---------- */
const KINDS={
  part2:{part:'Part 2',family:'listening',label:'應答問題',color:'orange',choices:3},
  listening:{part:'Part 3·4',family:'listening',label:'對話與獨白',color:'orange',choices:4},
  part5:{part:'Part 5',family:'reading',label:'句子填空',color:'purple',choices:4},
  part6:{part:'Part 6',family:'reading',label:'段落填空',color:'purple',choices:4},
  reading:{part:'Part 7',family:'reading',label:'閱讀理解',color:'purple',choices:4}};
const SET_KINDS=Object.keys(KINDS);
const FAMILY={listening:['part2','listening'],reading:['part5','part6','reading']};
const TASKS={grammar:['part5','part6'],reading:['reading'],listening:['part2','listening']};
const CAUSES={reading:['字彙不懂','文法觀念','找不到依據','被同義改寫誤導','時間不夠','粗心'],listening:['沒聽清楚','字彙不懂','跟不上速度','被相似音誤導','被同義改寫誤導','粗心']};
const ALL_CAUSES=[...new Set([...CAUSES.reading,...CAUSES.listening])];
const SKILLS=['詞性','動詞形式','時態與語態','介系詞','連接詞','代名詞與關係詞','字彙','比較與數量','句子插入'];
const MOCK_PLAN={mini:{part2:1,listening:2,part5:2,part6:1,reading:2},full:{part2:2,listening:4,part5:4,part6:2,reading:4}};
const SET_SECONDS={part2:180,listening:180,part5:180,part6:240};
const setSeconds=(kind,s)=>SET_SECONDS[kind]??s.questions.length*90;
const kindOf=id=>SET_KINDS.find(k=>(BANK[k]||[]).some(s=>s.id===id));
const findSet=(kind,id)=>(BANK[kind]||[]).find(s=>s.id===id);
const familyOf=kind=>KINDS[kind]?.family||'reading';
const letters='ABCD';
const blankLabel=q=>q.replace(/^Blank \[(\d)\]$/,'空格 ($1)');
const partTag=(kind,s)=>String(s.tag).startsWith('Part')?s.tag:`${KINDS[kind].part} · ${s.tag}`;
const meaningSegs=m=>String(m).split(/[；（）()]/).map(x=>x.trim()).filter(Boolean);
const qText=(kind,s,i)=>kind==='part6'?`${s.title} · ${blankLabel(s.questions[i].q)}`:s.questions[i].q;

const fresh=()=>({version:2,goal:90,days:{},history:[],wrong:{},cards:{},created:dateKey(),causes:[],skills:{},exams:[],level:null,voice:'file'});
let state=fresh(), storageOK=true;
function normalize(value){
  if(!value||![1,2].includes(value.version)||!value.days||!Array.isArray(value.history)||!value.cards||!value.wrong)throw Error('無法辨識的備份格式');
  const next=fresh(),today=dateKey();
  next.goal=[30,60,90,120].includes(value.goal)?value.goal:90;
  next.created=isDate(value.created)?value.created:today;
  next.level=['基礎','進階'].includes(value.level)?value.level:null;
  next.voice=value.voice==='browser'?'browser':'file';
  Object.entries(value.days).forEach(([k,v])=>{if(isDate(k)&&v&&Number.isFinite(v.seconds))next.days[k]={seconds:Math.max(0,Math.min(v.seconds,86400)),vocab:[...new Set((v.vocab||[]).filter(id=>BANK.vocabulary.some(c=>c.id===id)))],sets:[...new Set((v.sets||[]).filter(id=>kindOf(id)))]}});
  next.history=value.history.filter(h=>h&&[...SET_KINDS,'vocabulary'].includes(h.kind)&&Number.isInteger(h.correct)&&Number.isInteger(h.total)&&h.total>0&&h.correct>=0&&h.correct<=h.total&&isDate(h.date)).map(h=>({date:h.date,kind:h.kind,id:String(h.id||''),correct:h.correct,total:h.total,...(h.mode==='exam'?{mode:'exam'}:{})})).slice(-5000);
  Object.entries(value.cards).forEach(([id,c])=>{if(BANK.vocabulary.some(v=>v.id===id)&&c&&isDate(c.due)&&Number.isInteger(c.stage)&&c.stage>=0&&c.stage<=5)next.cards[id]={stage:c.stage,due:c.due}});
  Object.entries(value.wrong).forEach(([key,w])=>{const source=findSet(w?.kind,w?.id);if(source&&Number.isInteger(w.index)&&source.questions[w.index]&&key===`${w.kind}:${w.id}:${w.index}`)next.wrong[key]={kind:w.kind,id:w.id,index:w.index,stage:w.stage===1?1:0,due:isDate(w.due)?w.due:today,added:isDate(w.added)?w.added:today,cause:ALL_CAUSES.includes(w.cause)?w.cause:null,misses:Number.isInteger(w.misses)&&w.misses>0?w.misses:1}});
  if(Array.isArray(value.causes))next.causes=value.causes.filter(c=>c&&isDate(c.date)&&SET_KINDS.includes(c.kind)&&ALL_CAUSES.includes(c.cause)&&typeof c.key==='string').map(c=>({date:c.date,key:c.key,kind:c.kind,cause:c.cause,...(SKILLS.includes(c.skill)?{skill:c.skill}:{})})).slice(-3000);
  if(value.skills&&typeof value.skills==='object')Object.entries(value.skills).forEach(([k,v])=>{if(SKILLS.includes(k)&&Array.isArray(v)&&Number.isInteger(v[0])&&Number.isInteger(v[1])&&v[0]>=0&&v[0]<=v[1])next.skills[k]=[v[0],v[1]]});
  if(Array.isArray(value.exams))next.exams=value.exams.filter(x=>x&&isDate(x.date)&&['diagnostic','mock'].includes(x.type)&&Number.isInteger(x.correct)&&Number.isInteger(x.total)&&x.total>0&&x.correct<=x.total&&x.parts&&typeof x.parts==='object').map(x=>{const parts={};Object.entries(x.parts).forEach(([k,v])=>{if(SET_KINDS.includes(k)&&Array.isArray(v)&&Number.isInteger(v[0])&&Number.isInteger(v[1])&&v[0]<=v[1])parts[k]=[v[0],v[1]]});return{date:x.date,type:x.type,form:['A','B'].includes(x.form)?x.form:null,size:['mini','full'].includes(x.size)?x.size:null,correct:x.correct,total:x.total,seconds:Number.isFinite(x.seconds)?Math.max(0,Math.round(x.seconds)):0,limit:Number.isFinite(x.limit)?x.limit:null,band:typeof x.band==='string'?x.band.slice(0,12):null,parts}}).slice(-200);
  return next}
try{const raw=localStorage.getItem(KEY);if(raw)state=normalize(JSON.parse(raw))}catch(e){storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch(e){storageOK=false;toast('瀏覽器無法儲存紀錄，請匯出備份以免遺失。')}}
function day(){const k=dateKey();return state.days[k]??(state.days[k]={seconds:0,vocab:[],sets:[]})}
const pct=(a,b)=>b?Math.round(a/b*100):0;
const accuracy=kind=>{const rows=state.history.filter(h=>!kind||h.kind===kind);return rows.length?pct(rows.reduce((a,h)=>a+h.correct,0),rows.reduce((a,h)=>a+h.total,0)):null};
const complete=id=>state.history.some(h=>h.id===id);
const dueCards=()=>BANK.vocabulary.filter(v=>state.cards[v.id]&&state.cards[v.id].due<=dateKey());
const dueWrong=()=>Object.values(state.wrong).filter(w=>w.due<=dateKey());
const lastDiag=()=>state.exams.filter(x=>x.type==='diagnostic').at(-1)||null;
const totalQuestions=kinds=>kinds.reduce((n,k)=>n+BANK[k].reduce((m,s)=>m+s.questions.length,0),0);
const fmtTime=sec=>`${String(Math.floor(Math.max(0,sec)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,sec)%60)).padStart(2,'0')}`;

let view='home', filter='全部', partFilter='全部', search='', dueOnly=false, run=null, deck=null, exam=null, dict=null, speechRate=1, focusRemaining=25*60,focusOn=false,lastActive=Date.now(), timerTicks=0;
const mainNames={home:['學習總覽','OVERVIEW'],reading:['閱讀練習','READING'],listening:['聽力練習','LISTENING'],vocabulary:['單字複習','VOCABULARY'],exam:['診斷與模考','TESTS'],examrun:['測驗進行中','TEST'],review:['錯題筆記','REVIEW'],stats:['學習紀錄','YOUR PROGRESS'],quiz:['專注練習','PRACTICE'],flash:['單字練習','FLASHCARDS']};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}

/* ---------- 語音 ---------- */
const hasSpeech=()=>'speechSynthesis'in window&&typeof SpeechSynthesisUtterance!=='undefined';
let speechToken=0;
function stopSpeech(){speechToken++;if(hasSpeech())speechSynthesis.cancel();document.querySelectorAll('.speaking').forEach(el=>el.classList.remove('speaking'))}
function halt(){const a=$('#speech-audio');if(a)a.pause();stopSpeech()}
function englishVoices(){if(!hasSpeech())return[];const all=speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang));const rank=v=>/en-US/i.test(v.lang)?0:/en-GB/i.test(v.lang)?1:/en-AU|en-CA/i.test(v.lang)?2:3;return all.sort((a,b)=>rank(a)-rank(b))}
function parseTranscript(text){return String(text).split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const m=l.match(/^([A-Z][A-Za-z .]{0,20}):\s*(.+)$/);return m?{speaker:m[1],text:m[2]}:{speaker:'Narrator',text:l}})}
function speakQueue(items,onDone){if(!hasSpeech()){toast('此瀏覽器不支援英文語音播放，請改用新版 Chrome、Edge 或 Safari。');return false}stopSpeech();const token=speechToken,voices=englishVoices(),speakers=[...new Set(items.map(x=>x.speaker))];let i=0;const nextItem=()=>{if(token!==speechToken)return;if(i>=items.length){onDone&&onDone();return}const item=items[i++],si=speakers.indexOf(item.speaker),u=new SpeechSynthesisUtterance(item.text);u.lang='en-US';u.rate=speechRate;if(voices.length)u.voice=voices[si%voices.length];u.pitch=voices.length>si?1:[1,.78,1.22][si%3];u.onend=()=>setTimeout(nextItem,item.pause||350);u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error)){toast('語音播放失敗，請確認裝置已安裝英文語音。');stopSpeech()}};speechSynthesis.speak(u)};nextItem();return true}
function part2Items(q){return[{speaker:'Q',text:q.q,pause:900},...q.options.map((o,j)=>({speaker:'R',text:`${letters[j]}. ${o}`,pause:700}))]}

/* ---------- 版面 ---------- */
function nav(page){halt();view=page;filter='全部';partFilter='全部';search='';dueOnly=false;dict=null;render();window.scrollTo({top:0,behavior:'instant'})}
function shell(content){const active=view==='quiz'?familyOf(run?.kind):view==='flash'?'vocabulary':view==='examrun'?'exam':view;const wrongCount=dueWrong().length;return `<aside class="sidebar"><a href="#home" class="brand" data-nav="home"><span class="brand-icon">${icon('leaf')}</span><span>lingo<span class="brand-dot">.</span><small>TOEIC 700 練習室</small></span></a><p class="nav-caption">你的學習空間</p><nav aria-label="主選單">${[['home','學習總覽'],['reading','閱讀練習'],['listening','聽力練習'],['vocabulary','單字複習'],['exam','診斷模考'],['review','錯題筆記'],['stats','學習紀錄']].map(([id,label])=>`<button class="nav-item ${active===id?'active':''}" data-nav="${id}">${icon(id)}<span>${label}</span>${id==='review'&&wrongCount?`<span class="nav-count" title="今天到期">${wrongCount}</span>`:''}</button>`).join('')}</nav><div class="sidebar-goal"><span class="goal-art">${icon('flag')}</span><span class="eyebrow">一步一步，靠近目標</span><strong>下一站，700 分</strong><p>每天一點進步，<br>讓英文成為你的底氣。</p><div class="goal-tags"><span>${state.level?state.level+'程度':'尚未診斷'}</span><span>每日 ${state.goal} 分鐘</span></div></div><div class="sidebar-bottom"><span class="avatar">Y</span><span>我的學習帳本<small>紀錄儲存於此瀏覽器</small></span><span class="local-dot" title="本機儲存"></span></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">我的學習空間 <span>/</span> <strong>${mainNames[view][0]}</strong></div><div class="top-actions"><span class="date">${icon('calendar')}${new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span><button class="focus-button ${focusOn?'running':''}" data-action="focus" title="切換25分鐘專注計時">${icon('clock')}<span id="focus-label">${focusOn?'專注中':'專注計時'} ${fmtTime(focusRemaining)}</span></button></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="storage-warning">目前未能讀取或儲存本機紀錄，請至學習紀錄匯出備份。</div>':''}${content}</main><footer>每天進步一點，就離目標近一點。<span>原創多益風格練習 · 非 ETS 官方題庫 · 練習正確率不等同正式分數</span></footer></div>`}
function title(kicker,title,desc,aside=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="subtitle">${desc}</p></div>${aside}</div>`}

/* ---------- 推薦下一組（依程度與弱項） ---------- */
function nextSet(task){const kinds=TASKS[task]||[task];const order=kinds.slice().sort((a,b)=>(accuracy(a)??-1)-(accuracy(b)??-1));for(const k of order){const pool=BANK[k].filter(s=>!complete(s.id)),pref=pool.filter(s=>!state.level||s.level===state.level),s=pref[0]||pool[0];if(s)return{kind:k,set:s}}const k=order[0],list=BANK[k];return{kind:k,set:list[state.history.filter(h=>h.kind===k).length%list.length]}}
const taskDone=task=>day().sets.some(id=>TASKS[task].includes(kindOf(id)));
const doneSet=task=>{const id=day().sets.find(id=>TASKS[task].includes(kindOf(id)));return id?findSet(kindOf(id),id):null};
function streak(){let n=0,k=dateKey();if(!state.days[k]||(!state.days[k].seconds&&!state.days[k].sets.length&&!state.days[k].vocab.length))k=shiftDay(k,-1);while(state.days[k]&&(state.days[k].seconds>0||state.days[k].sets.length||state.days[k].vocab.length)){n++;k=shiftDay(k,-1)}return n}
function weekChart(){return `<div class="week-chart">${Array.from({length:7},(_,i)=>{const k=shiftDay(dateKey(),i-6),minutes=Math.round((state.days[k]?.seconds||0)/60),label=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',weekday:'short'}).format(new Date(k+'T12:00:00+08:00')).replace('週','');return `<div class="chart-column ${i===6?'today':''}"><span class="bar-value">${minutes}</span><div class="bar-track"><div class="bar" style="height:${Math.min(100,pct(minutes,state.goal))}%"></div></div><span class="day-label">${label}</span></div>`}).join('')}</div>`}
function diagBanner(){const d=lastDiag();if(!d)return `<div class="diag-banner">${icon('exam')}<div><strong>先做一次程度診斷</strong><p>約 30 分鐘、33 題，涵蓋 Part 2 到 Part 7。系統會依結果安排基礎或進階題組，並找出優先加強的題型。</p></div><button class="button primary" data-action="diag-start">開始診斷 ${icon('play')}</button></div>`;const left=14-daysBetween(d.date,dateKey());return left<=0?`<div class="diag-banner due">${icon('calendar')}<div><strong>距離上次診斷已滿兩週</strong><p>做一次後測（換一套題目），比較各 Part 的進步幅度。上次結果：${esc(d.band)}，正確率 ${pct(d.correct,d.total)}%。</p></div><button class="button primary" data-action="diag-start">開始後測 ${icon('play')}</button></div>`:`<div class="diag-banner quiet">${icon('flag')}<div><strong>目前程度：${esc(d.band)}（${pct(d.correct,d.total)}%）</strong><p>題組優先安排「${state.level||'基礎'}」難度，並先練正確率最低的題型。${left} 天後建議做後測。</p></div><button class="button secondary" data-nav="exam">查看測驗</button></div>`}
function home(){const d=day(),minutes=Math.floor(d.seconds/60),vCount=d.vocab.length,taskList=[['vocabulary',vCount>=10,'複習 10 個單字',`${Math.min(vCount,10)} / 10 個`],...[['grammar','完成一組文法（Part 5 / 6）'],['reading','完成一組閱讀（Part 7）'],['listening','完成一組聽力（Part 2–4）']].map(([t,label])=>{const done=taskDone(t),s=done?doneSet(t):nextSet(t).set;return[t,done,label,(done?'':'建議：')+s.title]})],tasks=taskList.filter(t=>t[1]).length,readQ=totalQuestions(FAMILY.reading),listenQ=totalQuestions(FAMILY.listening);
return title('A LITTLE EVERY DAY','把今天的努力，變成明天的實力。','文法、閱讀、聽力、單字，一起朝多益 700 分前進。',`<div class="target-pill">${icon('flag')}目標分數 <strong>700</strong></div>`)+`<section class="hero"><div class="hero-content"><span class="hero-label"><span></span> YOUR DAILY ENGLISH ROUTINE</span><h2>今天，也為自己<br>累積一點英文力。</h2><p>從一組練習開始，找到自己的學習節奏。<br>系統會優先安排你最需要加強的題型。</p><button class="button light" data-action="daily">${icon('play')}開始今日練習</button><span class="hero-foot">${tasks}/4 項任務完成 · 每日計畫 ${state.goal} 分鐘${dueWrong().length?` · ${dueWrong().length} 題錯題到期`:''}</span></div><div class="hero-illustration" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="deco-star star-one">✦</span><span class="deco-star star-two">✦</span><div class="floating-word"><span class="word-dot"></span>Every day counts.</div><div class="illustration-book"><div class="book-spine"></div><span class="book-small">A LITTLE PROGRESS</span><strong>HELLO,<br>FUTURE<br>ME<span>✦</span></strong><div class="book-rule"></div><span class="book-bottom">ENGLISH FOR YOUR NEXT CHAPTER</span></div><div class="floating-score">${icon('check')}<div>今日任務<small>${tasks} / 4 已完成</small></div></div><div class="art-spark">✳</div></div></section>${diagBanner()}<section class="metric-grid"><article class="metric"> <span class="metric-icon purple">${icon('clock')}</span><div><span>今日學習</span><strong>${minutes}<small> / ${state.goal} 分鐘</small></strong></div></article><article class="metric"><span class="metric-icon orange">${icon('spark')}</span><div><span>連續學習</span><strong>${streak()}<small> 天</small></strong></div></article><article class="metric"><span class="metric-icon green">${icon('vocabulary')}</span><div><span>已練習單字</span><strong>${Object.keys(state.cards).length}<small> / ${BANK.vocabulary.length} 個</small></strong></div></article><article class="metric"><span class="metric-icon blue">${icon('check')}</span><div><span>測驗正確率</span><strong>${accuracy()===null?'—':accuracy()+'%'}<small>${accuracy()===null?' 尚無紀錄':' 累計作答'}</small></strong></div></article></section><div class="section-heading"><div><h2>今天，想練習什麼？</h2><p>四種練習，讓英文能力穩穩向前。</p></div><span class="quiet-label">選擇你的學習模式</span></div><section class="module-grid four">${[['reading','閱讀與文法','READ & UNDERSTAND','從句子填空到多篇閱讀，<br>練文法，也練找線索。',`Part 5–7 · ${readQ} 題`,'purple'],['listening','聽力練習','LISTEN & CONNECT','從快速應答到職場廣播，<br>讓耳朵跟上英文的節奏。',`Part 2–4 · ${listenQ} 題`,'orange'],['vocabulary','單字複習','WORDS THAT STICK','用例句理解，用間隔複習記住，<br>把單字變成用得上的能力。',`${BANK.vocabulary.length} 個詞組 · 間隔複習`,'green'],['exam','診斷與模考','TEST YOURSELF','程度診斷、兩週後測，<br>加上計時模考練節奏。','診斷 · 迷你／完整模考','blue']].map(([id,label,en,desc,info,color])=>`<article class="module-card ${color}"><div class="module-top"><span class="module-icon">${icon(id)}</span><span class="module-en">${en}</span></div><h3>${label}</h3><p>${desc}</p><div class="module-bottom"><span>${info}</span><button class="round-button" data-nav="${id}" aria-label="開始${label}">${icon('play')}</button></div></article>`).join('')}</section><section class="lower-grid"><article class="panel tasks-panel"><div class="section-heading"><h2>今日小目標</h2><span class="count-pill">${tasks} / 4</span></div>${taskList.map(([kind,done,label,sub])=>`<button class="task-row" data-task="${kind}"><span class="task-check ${done?'done':''}">${done?icon('check'):''}</span><span><strong>${label}</strong><small>${esc(sub)}</small></span><span class="task-status">${done?'已完成':'開始練習'}</span></button>`).join('')}</article><article class="panel week-panel"><div class="section-heading"><h2>本週的累積</h2><span class="quiet-label">分鐘 / 天</span></div>${weekChart()}<p class="chart-note">每一次開始，都值得被記錄。</p></article></section><div class="study-note">${icon('leaf')}<p><strong>今天的小提醒</strong>答錯時，花五秒標記錯誤原因。知道自己錯在哪一類，下一次才知道要調整什麼。</p></div>`}

/* ---------- 題組列表 ---------- */
function catalog(family){const isRead=family==='reading',kinds=FAMILY[family],parts=['全部',...kinds.map(k=>KINDS[k].part)],items=kinds.filter(k=>partFilter==='全部'||KINDS[k].part===partFilter).flatMap(k=>BANK[k].filter(s=>filter==='全部'||s.level===filter).map(s=>({kind:k,s}))),doneCount=kinds.reduce((n,k)=>n+BANK[k].filter(s=>complete(s.id)).length,0),setCount=kinds.reduce((n,k)=>n+BANK[k].length,0),rec=nextSet(isRead?'grammar':'listening');
return title(isRead?'READ & UNDERSTAND':'LISTEN & CONNECT',isRead?'讀懂句子，也讀懂線索。':'讓耳朵，慢慢跟上英文。',isRead?'Part 5 句子填空、Part 6 段落填空、Part 7 閱讀理解；作答後查看中文解析與答案依據。':'Part 2 應答問題、Part 3 對話、Part 4 獨白；可變速、重播，作答後查看逐字稿並做聽寫。')+`<div class="toolbar wrap"><div class="tabs" role="group" aria-label="題型篩選">${parts.map(p=>`<button class="${partFilter===p?'selected':''}" data-part-filter="${p}">${p}</button>`).join('')}</div><div class="tabs" role="group" aria-label="難度篩選">${['全部','基礎','進階'].map(f=>`<button class="${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><span class="quiet-label">${doneCount} / ${setCount} 組已完成</span></div><p class="recommend">${icon('spark')}建議下一組：<button class="text-button" data-start="${rec.kind}:${rec.set.id}">${KINDS[rec.kind].part} · ${esc(rec.set.title)}</button><span class="quiet-label">（依你的程度與各 Part 正確率安排）</span></p><section class="exercise-grid">${items.map(({kind,s})=>`<article class="panel exercise-card"><div class="exercise-top"><span class="exercise-icon ${isRead?'purple':'orange'}">${icon(family)}</span><span class="tag">${s.level}</span></div><p class="eyebrow">${esc(partTag(kind,s))}</p><h2>${esc(s.title)}</h2><div class="exercise-meta"><span>${icon('clock')}${s.minutes}–${s.minutes+5} 分鐘</span><span>${s.questions.length} 題</span>${complete(s.id)?'<span class="completed-label">已完成</span>':''}</div><button class="button ${isRead?'primary':'warm'}" data-start="${kind}:${s.id}">${complete(s.id)?'再次練習':'開始練習'}${icon('play')}</button></article>`).join('')}</section>`}

/* ---------- 題組呈現（練習與測驗共用） ---------- */
function causeChips(key){const w=state.wrong[key];if(!w)return'';return `<div class="cause-box"><span>這題錯在哪裡？</span><div class="cause-chips">${CAUSES[familyOf(w.kind)].map(c=>`<button class="chip ${w.cause===c?'selected':''}" data-cause="${esc(key)}|${c}" aria-pressed="${w.cause===c}">${c}</button>`).join('')}</div></div>`}
function passagePanel(kind,s,ctx){const submitted=ctx.submitted;
  if(kind==='listening'){const browser=state.voice==='browser';return `<article class="panel passage audio-panel"><div class="audio-art">${icon('listening')}<span class="audio-wave">▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▇ ▃ ▅ ▂</span></div><span class="eyebrow">LISTEN CLOSELY</span><h2>先看題目，再聽重點。</h2><p class="subtitle">播放前先掃過三個問題，聽的時候就知道要抓什麼。</p><div class="tabs voice-tabs" role="group" aria-label="音源"><button class="${!browser?'selected':''}" data-voice="file">預製音檔</button><button class="${browser?'selected':''}" data-voice="browser">雙聲道語音</button></div>${browser?`<div class="speech-controls"><button class="button warm" data-action="voice-play">${icon('play')}播放對話</button><button class="button secondary" data-action="voice-stop">${icon('stop')}停止</button><label>語速 <select id="speech-rate">${[.8,1,1.2].map(r=>`<option value="${r}" ${speechRate===r?'selected':''}>${r.toFixed(1)} 倍</option>`).join('')}</select></label></div><p class="audio-caption">使用此裝置的瀏覽器英文語音，不同說話者以不同聲音或音高播放。</p>`:`<audio id="speech-audio" controls preload="metadata" src="audio/${s.id}.wav">此瀏覽器不支援音訊播放。</audio><div class="audio-tools"><label>播放速度 <select id="audio-rate"><option value="0.8">0.8 倍</option><option value="1" selected>1.0 倍</option><option value="1.2">1.2 倍</option></select></label><button class="text-button" data-action="replay">${icon('review')}重新播放</button></div><div id="audio-error" role="alert"></div><p class="audio-caption">英文合成語音（單一聲音）· 若要分辨說話者，請切換「雙聲道語音」</p>`}${submitted?`<details open><summary>英文逐字稿</summary><div class="english transcript">${esc(s.transcript).replace(/\n/g,'<br><br>')}</div></details>`:'<div class="transcript-locked">'+icon('reading')+' 提交答案後，開啟逐字稿與中文解析。</div>'}</article>`}
  if(kind==='part2'){return `<article class="panel passage audio-panel"><div class="audio-art">${icon('listening')}<span class="audio-wave">▂ ▅ ▃ ▇ ▄ ▆</span></div><span class="eyebrow">QUESTION — RESPONSE</span><h2>聽問句，選最自然的回應。</h2><p class="subtitle">每題先播放一句問句或敘述，接著播放 A、B、C 三個回應。正式考試不印選項，所以交卷前只顯示字母。</p><div class="speech-controls"><label>語速 <select id="speech-rate">${[.8,1,1.2].map(r=>`<option value="${r}" ${speechRate===r?'selected':''}>${r.toFixed(1)} 倍</option>`).join('')}</select></label>${!submitted?`<label class="checkbox-label"><input type="checkbox" id="show-text" ${ctx.showText?'checked':''}>顯示文字（無法播放時使用）</label>`:''}</div>${!hasSpeech()?'<p class="storage-warning">此瀏覽器不支援英文語音，請勾選「顯示文字」改用閱讀方式練習。</p>':''}<p class="audio-caption">使用此裝置的瀏覽器英文語音，問句與回應使用不同聲音或音高。</p><div class="trap-note"><strong>常見陷阱</strong><p>重複題目的字、發音相似的字、WH 問句用 Yes / No 回答，通常是錯誤選項。</p></div></article>`}
  if(kind==='part5')return'';
  const text=kind==='part6'?esc(s.text).replace(/\[(\d)\]/g,'<span class="blank">($1) ______</span>').replace(/\n/g,'<br>'):esc(s.text).replace(/\n/g,'<br>');
  return `<article class="panel passage"><div class="email-heading"><span class="mail-dot"></span><span>${esc(s.from)}</span></div><h2 class="english">${esc(s.subject)}</h2><div class="english passage-text">${text}</div></article>`}
function questionsPanel(kind,s,ctx){const n=s.questions.length;return `<section class="questions" aria-label="測驗題目">${s.questions.map((q,i)=>{const chosen=ctx.ans(i),key=`${kind}:${s.id}:${i}`,hide=kind==='part2'&&!ctx.submitted&&!ctx.showText;return `<article class="panel question"><div class="question-heading"><span class="question-number">${String(i+1).padStart(2,'0')}</span>${kind==='part2'?`<h3>${ctx.submitted||ctx.showText?`<span class="english">${esc(q.q)}</span>`:'第 '+(i+1)+' 題'}</h3><button class="sound-button" data-p2play="${i}" aria-label="播放第 ${i+1} 題">${icon('sound')}</button>`:`<h3 class="english">${esc(kind==='part6'?blankLabel(q.q):q.q)}</h3>`}</div>${q.skill&&ctx.submitted?`<span class="skill-tag">${esc(q.skill)}</span>`:''}<div class="options ${kind==='part2'?'three':''}" role="group" aria-label="第${i+1}題選項">${q.options.map((o,j)=>`<button class="option ${chosen===j?'chosen':''} ${ctx.submitted?(q.answer===j?'correct':chosen===j?'incorrect':''):''}" ${ctx.attr}="${i}:${j}" aria-pressed="${chosen===j}" ${ctx.submitted?'disabled':''}><span class="option-letter">${letters[j]}</span><span class="english">${hide?'<span class="hidden-option">選項 '+letters[j]+'</span>':esc(o)}</span>${ctx.submitted&&q.answer===j?icon('check'):''}</button>`).join('')}</div>${ctx.submitted?`<div class="explanation"><strong>${chosen===q.answer?'答對了':chosen===undefined?'未作答':'再記住這個線索'} · 正確答案 ${letters[q.answer]}</strong><p>${esc(q.explain)}</p></div>${chosen!==q.answer?causeChips(key):''}`:''}</article>`}).join('')}${ctx.footer||''}</section>`}
function dictationPanel(kind,s){const lines=kind==='listening'?parseTranscript(s.transcript).map(x=>x.text):s.questions.flatMap(q=>[q.q,q.options[q.answer]]);if(!dict||dict.id!==s.id)dict={id:s.id,idx:0,input:'',result:null};return `<article class="panel dictation"><div class="section-heading"><div><h2>${icon('pen')} 聽寫練習</h2><p>聽一句、寫一句。寫不出來的字，就是下次要特別注意的音。</p></div></div><div class="dict-row"><label>選擇句子 <select id="dict-select">${lines.map((l,i)=>`<option value="${i}" ${i===dict.idx?'selected':''}>第 ${i+1} 句（${l.split(/\s+/).length} 字）</option>`).join('')}</select></label><button class="button warm" data-action="dict-play">${icon('sound')}播放這句</button></div><textarea id="dict-input" rows="2" placeholder="聽完後，把聽到的英文打在這裡…" aria-label="聽寫輸入">${esc(dict.input)}</textarea><div class="dict-row"><button class="button primary" data-action="dict-check">${icon('check')}核對</button><span class="quiet-label">使用瀏覽器英文語音播放，可調整上方語速。</span></div>${dict.result?`<div class="dict-result"><strong>聽對 ${dict.result.hit} / ${dict.result.total} 字（${pct(dict.result.hit,dict.result.total)}%）</strong><p class="english">${dict.result.html}</p><p class="quiet-label">綠色是聽對的字，紅色是漏掉或寫錯的字。</p></div>`:''}</article>`}
const tokens=s=>String(s).toLowerCase().replace(/[’‘]/g,"'").replace(/[^a-z0-9'$.\s-]/g,' ').replace(/(\.)(\s|$)/g,' ').split(/\s+/).filter(Boolean);
function compareDictation(ref,input){const a=String(ref).split(/\s+/).filter(Boolean),at=a.map(w=>tokens(w).join(' ')),b=tokens(input),m=at.length,n=b.length,dp=Array.from({length:m+1},()=>new Array(n+1).fill(0));for(let i=m-1;i>=0;i--)for(let j=n-1;j>=0;j--)dp[i][j]=at[i]&&at[i]===b[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);const ok=new Array(m).fill(false);let i=0,j=0;while(i<m&&j<n){if(at[i]&&at[i]===b[j]){ok[i]=true;i++;j++}else if(dp[i+1][j]>=dp[i][j+1])i++;else j++}const counted=at.filter(Boolean).length;return{hit:ok.filter(Boolean).length,total:counted,html:a.map((w,k)=>`<span class="${ok[k]?'diff-ok':'diff-miss'}">${esc(w)}</span>`).join(' ')}}

/* ---------- 練習流程 ---------- */
function start(kind,id){halt();const s=findSet(kind,id);if(!s)return;run={kind,id,answers:{},submitted:false,showText:false,result:null};dict=null;view='quiz';render();window.scrollTo(0,0)}
function quiz(){const s=findSet(run.kind,run.id),kind=run.kind,meta=KINDS[kind],answered=Object.keys(run.answers).length,correct=s.questions.reduce((n,q,i)=>n+Number(run.answers[i]===q.answer),0),r=run.result;
  const banner=run.submitted?`<div class="result-banner"><span class="result-check">${icon('check')}</span><div><h2>練習完成，累積一點新實力。</h2><p>答對 ${correct} / ${s.questions.length} 題 · 正確率 ${pct(correct,s.questions.length)}% · ${correct===s.questions.length?'本組全對，繼續保持！':'錯題已排入明天複習，記得標記錯誤原因'}${r&&r.mastered?` · ${r.mastered} 題錯題已熟練移出`:''}${r&&r.advanced?` · ${r.advanced} 題錯題進入第二輪`:''}${r&&r.early?` · ${r.early} 題錯題未到複習日，不計入進度`:''}</p></div><button class="button primary" data-action="next">下一組練習</button></div>`:'';
  const ctx={ans:i=>run.answers[i],submitted:run.submitted,attr:'data-answer',showText:run.showText,footer:`<div class="submit-row"><span>${run.submitted?'已儲存學習紀錄':`已作答 ${answered} / ${s.questions.length} 題`}</span>${!run.submitted?`<button class="button primary" data-action="submit" ${answered!==s.questions.length?'disabled':''}>提交答案 ${icon('check')}</button>`:`<button class="button primary" data-action="next">下一組練習 ${icon('play')}</button>`}</div>`};
  const left=passagePanel(kind,s,ctx);
  return `<button class="back-link" data-nav="${meta.family}">返回${meta.family==='listening'?'聽力':'閱讀'}列表</button>`+title(esc(partTag(kind,s)),esc(s.title),`共 ${s.questions.length} 題 · ${s.level} · ${run.submitted?'已完成本次練習':'先獨立作答，再查看解析'}`)+banner+`<div class="quiz-layout ${left?'':'single'}">${left}${questionsPanel(kind,s,ctx)}</div>${run.submitted&&meta.family==='listening'?dictationPanel(kind,s):''}`}
function markWrong(kind,id,index){const key=`${kind}:${id}:${index}`,old=state.wrong[key],today=dateKey();state.wrong[key]={kind,id,index,stage:0,due:shiftDay(today,1),added:old?.added||today,cause:null,misses:(old?.misses||0)+1}}
function markCorrect(key){const w=state.wrong[key];if(!w)return null;if(w.due>dateKey())return'early';if(w.stage>=1){delete state.wrong[key];return'mastered'}w.stage=1;w.due=shiftDay(dateKey(),3);return'advanced'}
function tallySkill(q,ok){if(!q.skill||!SKILLS.includes(q.skill))return;const t=state.skills[q.skill]||[0,0];state.skills[q.skill]=[t[0]+Number(ok),t[1]+1]}
function gradeSet(kind,s,getAns,mode){let correct=0;const res={mastered:0,advanced:0,early:0};s.questions.forEach((q,i)=>{const ok=getAns(i)===q.answer;tallySkill(q,ok);if(ok){correct++;const r=markCorrect(`${kind}:${s.id}:${i}`);if(r)res[r]++}else markWrong(kind,s.id,i)});state.history.push({date:dateKey(),kind,id:s.id,correct,total:s.questions.length,...(mode?{mode}:{})});return{correct,res}}
function submitQuiz(){if(!run||run.submitted)return;const s=findSet(run.kind,run.id);if(Object.keys(run.answers).length!==s.questions.length)return;run.submitted=true;const g=gradeSet(run.kind,s,i=>run.answers[i]);run.result=g.res;if(!day().sets.includes(s.id))day().sets.push(s.id);save();halt();render();window.scrollTo({top:0,behavior:'smooth'})}
function setCause(key,cause){const w=state.wrong[key];if(!w||!CAUSES[familyOf(w.kind)].includes(cause))return;const today=dateKey();if(w.cause===cause){w.cause=null;state.causes=state.causes.filter(c=>!(c.key===key&&c.date===today))}else{w.cause=cause;state.causes=state.causes.filter(c=>!(c.key===key&&c.date===today));const q=findSet(w.kind,w.id).questions[w.index];state.causes.push({date:today,key,kind:w.kind,cause,...(q.skill?{skill:q.skill}:{})});state.causes=state.causes.slice(-3000)}save()}

/* ---------- 診斷與模考 ---------- */
function bandOf(p){return p<45?{band:'起步',level:'基礎'}:p<65?{band:'基礎鞏固',level:'基礎'}:p<80?{band:'進階衝刺',level:'進階'}:{band:'接近目標',level:'進階'}}
function startExam(type,size){halt();let sets,form=null,limit=null;if(type==='diagnostic'){form=state.exams.filter(x=>x.type==='diagnostic').length%2===0?'A':'B';sets=BANK.forms[form].map(([k,id])=>({kind:k,id}))}else{const plan=MOCK_PLAN[size]||MOCK_PLAN.mini;sets=SET_KINDS.flatMap(k=>shuffle(BANK[k]).slice(0,plan[k]||0).map(s=>({kind:k,id:s.id})));limit=sets.reduce((n,x)=>n+setSeconds(x.kind,findSet(x.kind,x.id)),0)}exam={type,size:size||null,form,sets,idx:0,answers:{},submitted:false,elapsed:0,limit,confirming:false,showText:false,record:null};view='examrun';render();window.scrollTo(0,0)}
function examTotals(){let answered=0,total=0;exam.sets.forEach(x=>{const s=findSet(x.kind,x.id);s.questions.forEach((_,i)=>{total++;if(exam.answers[`${x.kind}:${x.id}:${i}`]!==undefined)answered++})});return{answered,total}}
function submitExam(auto){if(!exam||exam.submitted)return;exam.submitted=true;exam.confirming=false;const parts={};let correct=0,total=0;exam.sets.forEach(x=>{const s=findSet(x.kind,x.id),g=gradeSet(x.kind,s,i=>exam.answers[`${x.kind}:${x.id}:${i}`],'exam'),p=parts[x.kind]||[0,0];parts[x.kind]=[p[0]+g.correct,p[1]+s.questions.length];correct+=g.correct;total+=s.questions.length});const rec={date:dateKey(),type:exam.type,form:exam.form,size:exam.size,correct,total,seconds:Math.round(exam.elapsed),limit:exam.limit,band:null,parts};if(exam.type==='diagnostic'){const b=bandOf(pct(correct,total));rec.band=b.band;state.level=b.level}state.exams.push(rec);exam.record=rec;exam.idx=-1;save();halt();render();window.scrollTo({top:0,behavior:'smooth'});if(auto)toast('時間到，已自動交卷。')}
function examHub(){const exams=state.exams.slice().reverse(),d=lastDiag(),miniMin=Math.round(SET_KINDS.reduce((n,k)=>n+(MOCK_PLAN.mini[k]||0)*(SET_SECONDS[k]??270),0)/60),fullMin=Math.round(SET_KINDS.reduce((n,k)=>n+(MOCK_PLAN.full[k]||0)*(SET_SECONDS[k]??270),0)/60),nextForm=state.exams.filter(x=>x.type==='diagnostic').length%2===0?'A':'B';
return title('TEST YOURSELF','先知道自己在哪裡，再決定怎麼練。','程度診斷用來分級與找弱項；計時模考混合各 Part，練習節奏與耐力。')+`${exam&&!exam.submitted?`<div class="diag-banner due">${icon('clock')}<div><strong>有一份未完成的測驗</strong><p>已作答 ${examTotals().answered} / ${examTotals().total} 題。開始新的測驗會取代它。</p></div><button class="button primary" data-action="exam-resume">繼續作答 ${icon('play')}</button></div>`:''}<section class="exam-grid"><article class="panel exam-card"><span class="exercise-icon purple">${icon('exam')}</span><p class="eyebrow">DIAGNOSTIC</p><h2>${d?'兩週後測':'程度診斷'}（第 ${nextForm} 套）</h2><p>33 題、不計時，涵蓋 Part 2 到 Part 7。A、B 兩套輪流使用，方便前後比較。完成後依正確率調整題組難度。</p><div class="exercise-meta"><span>${icon('clock')}約 30 分鐘</span><span>33 題</span>${d?`<span>上次 ${d.date}</span>`:''}</div><button class="button primary" data-action="diag-start">${d?'開始後測':'開始診斷'}${icon('play')}</button></article><article class="panel exam-card"><span class="exercise-icon orange">${icon('clock')}</span><p class="eyebrow">MINI MOCK</p><h2>迷你模考</h2><p>隨機抽題，各 Part 交錯出現。依多益節奏計時：Part 5 每題 30 秒、Part 7 每題 90 秒，時間到自動交卷。</p><div class="exercise-meta"><span>${icon('clock')}${miniMin} 分鐘</span><span>${SET_KINDS.reduce((n,k)=>n+(MOCK_PLAN.mini[k]||0)*({part2:5,listening:3,part5:6,part6:4,reading:3}[k]),0)} 題</span></div><button class="button warm" data-action="mock-mini">開始迷你模考${icon('play')}</button></article><article class="panel exam-card"><span class="exercise-icon green">${icon('flag')}</span><p class="eyebrow">FULL MOCK</p><h2>加長模考</h2><p>題量加倍，練習長時間專注。建議每週一次，固定在相同時段，比較作答時間與正確率。</p><div class="exercise-meta"><span>${icon('clock')}${fullMin} 分鐘</span><span>${SET_KINDS.reduce((n,k)=>n+(MOCK_PLAN.full[k]||0)*({part2:5,listening:3,part5:6,part6:4,reading:3}[k]),0)} 題</span></div><button class="button secondary" data-action="mock-full">開始加長模考${icon('play')}</button></article></section><p class="quiet-label">診斷分級是依本練習題庫的正確率粗略分組，不能換算為正式多益分數。目前題庫有限，模考可能抽到做過的題組。</p><article class="panel history-panel"><div class="section-heading"><h2>測驗紀錄</h2><span class="quiet-label">最近 20 次</span></div>${exams.length?`<div class="table-scroll"><table><thead><tr><th>日期</th><th>類型</th><th>正確率</th><th>用時</th><th>各 Part</th></tr></thead><tbody>${exams.slice(0,20).map(x=>`<tr><td>${x.date}</td><td>${x.type==='diagnostic'?`診斷 ${x.form||''}${x.band?' · '+esc(x.band):''}`:x.size==='full'?'加長模考':'迷你模考'}</td><td><span class="score-pill">${pct(x.correct,x.total)}%</span> ${x.correct}/${x.total}</td><td>${fmtTime(x.seconds)}${x.limit?' / '+fmtTime(x.limit):''}</td><td class="part-cells">${SET_KINDS.filter(k=>x.parts[k]).map(k=>`${KINDS[k].part} ${pct(...x.parts[k])}%`).join('、')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-copy">尚無測驗紀錄。建議先做一次程度診斷。</p>'}</article>`}
function examRun(){if(!exam)return examHub();const{answered,total}=examTotals(),label=exam.type==='diagnostic'?`程度診斷 · 第 ${exam.form} 套`:exam.size==='full'?'加長模考':'迷你模考';
  const pills=`<div class="exam-pills" role="tablist" aria-label="題組">${exam.sets.map((x,i)=>{const s=findSet(x.kind,x.id),done=s.questions.every((_,q)=>exam.answers[`${x.kind}:${x.id}:${q}`]!==undefined);return `<button class="pill ${i===exam.idx?'current':''} ${done?'done':''}" data-exam-go="${i}">${KINDS[x.kind].part}<small>${i+1}</small></button>`}).join('')}${exam.submitted?`<button class="pill ${exam.idx===-1?'current':''}" data-exam-go="-1">成績</button>`:''}</div>`;
  const bar=`<div class="exam-bar"><div><strong>${label}</strong><span class="quiet-label">${exam.submitted?'已交卷 · 可逐組查看解析':`已作答 ${answered} / ${total} 題`}</span></div><span class="exam-timer ${exam.limit&&exam.limit-exam.elapsed<120&&!exam.submitted?'urgent':''}" id="exam-timer">${icon('clock')}${exam.limit?(exam.submitted?'用時 '+fmtTime(exam.elapsed):'剩餘 '+fmtTime(exam.limit-exam.elapsed)):'已用 '+fmtTime(exam.elapsed)}</span>${!exam.submitted?`<button class="button primary" data-action="exam-submit">${exam.confirming?`還有 ${total-answered} 題未作答，確定交卷`:'交卷'} ${icon('check')}</button>`:`<button class="button secondary" data-nav="exam">回到測驗列表</button>`}</div>`;
  if(exam.submitted&&exam.idx===-1)return title('TEST RESULT','測驗完成，看看哪裡最需要加強。',`${exam.record.date} · 用時 ${fmtTime(exam.record.seconds)}`)+bar+pills+examResult();
  const x=exam.sets[exam.idx],s=findSet(x.kind,x.id),meta=KINDS[x.kind],ctx={ans:i=>exam.answers[`${x.kind}:${x.id}:${i}`],submitted:exam.submitted,attr:'data-exam-answer',showText:exam.showText,footer:`<div class="submit-row"><button class="button secondary" data-action="exam-prev" ${exam.idx===0?'disabled':''}>上一組</button><span>第 ${exam.idx+1} / ${exam.sets.length} 組</span>${exam.idx<exam.sets.length-1?`<button class="button primary" data-action="exam-next">下一組 ${icon('play')}</button>`:exam.submitted?`<button class="button primary" data-exam-go="-1">查看成績</button>`:`<button class="button primary" data-action="exam-submit">${exam.confirming?'確定交卷':'交卷'} ${icon('check')}</button>`}</div>`},left=passagePanel(x.kind,s,ctx);
  return title(`${meta.part} · ${meta.label}`,esc(s.title),exam.submitted?'解析模式 · 答錯的題目可標記錯誤原因':'作答中 · 可用上方按鈕切換題組')+bar+pills+`<div class="quiz-layout ${left?'':'single'}">${left}${questionsPanel(x.kind,s,ctx)}</div>`}
function examResult(){const r=exam.record,p=pct(r.correct,r.total),prev=r.type==='diagnostic'?state.exams.filter(x=>x.type==='diagnostic'&&x!==r).at(-1):null,weak=SET_KINDS.filter(k=>r.parts[k]).sort((a,b)=>pct(...r.parts[a])-pct(...r.parts[b])).slice(0,2),wrongList=exam.sets.flatMap(x=>{const s=findSet(x.kind,x.id);return s.questions.map((q,i)=>({x,s,q,i})).filter(o=>exam.answers[`${x.kind}:${x.id}:${o.i}`]!==o.q.answer)});
  return `<section class="lower-grid"><article class="panel band-card"><p class="eyebrow">${r.type==='diagnostic'?'LEVEL':'SCORE'}</p><h2>${r.type==='diagnostic'?`程度分組：${esc(r.band)}`:'模考正確率'}</h2><strong class="big-number">${p}<small>%</small></strong><p>答對 ${r.correct} / ${r.total} 題${r.limit?` · 用時 ${fmtTime(r.seconds)} / ${fmtTime(r.limit)}`:` · 用時 ${fmtTime(r.seconds)}`}</p>${r.type==='diagnostic'?`<p>接下來的每日題組會優先安排「${state.level}」難度。${prev?`與上次（${prev.date}）相比：${p-pct(prev.correct,prev.total)>=0?'+':''}${p-pct(prev.correct,prev.total)} 個百分點。`:'兩週後做第 '+(r.form==='A'?'B':'A')+' 套後測，比較進步幅度。'}</p>`:''}<p class="quiet-label">依本題庫正確率粗略分組，不代表正式多益分數。</p></article><article class="panel skill-panel"><h2>各 Part 正確率</h2>${SET_KINDS.filter(k=>r.parts[k]).map(k=>{const v=pct(...r.parts[k]),pv=prev&&prev.parts[k]?pct(...prev.parts[k]):null;return `<div class="skill-row"><span>${KINDS[k].part}</span><div class="skill-track"><span style="width:${v}%"></span></div><strong>${v}%${pv!==null?`<small class="${v-pv>=0?'up':'down'}"> ${v-pv>=0?'+':''}${v-pv}</small>`:''}</strong></div>`}).join('')}<p class="quiet-label">優先加強：${weak.map(k=>KINDS[k].part+' '+KINDS[k].label).join('、')}</p></article></section><article class="panel"><div class="section-heading"><div><h2>答錯 ${wrongList.length} 題</h2><p>已排入錯題筆記（明天開始複習）。現在先標記每題的錯誤原因。</p></div></div>${wrongList.length?wrongList.map(({x,s,q,i})=>`<div class="exam-wrong"><span class="tag">${KINDS[x.kind].part} · ${esc(s.title)}</span><p class="english">${esc(x.kind==='part6'?blankLabel(q.q):q.q)}</p><p><strong>正確答案 ${letters[q.answer]}. <span class="english">${esc(q.options[q.answer])}</span></strong>${exam.answers[`${x.kind}:${x.id}:${i}`]===undefined?' · 未作答':''}</p><p class="quiet-label">${esc(q.explain)}</p>${causeChips(`${x.kind}:${x.id}:${i}`)}</div>`).join(''):'<p>全部答對！</p>'}</article>`}

/* ---------- 單字 ---------- */
function vocab(){const cards=BANK.vocabulary.filter(v=>(filter==='全部'||v.tag===filter)&&(!dueOnly||(state.cards[v.id]&&state.cards[v.id].due<=dateKey()))&&(!search||[v.word,v.meaning,v.phrase].some(t=>t.toLowerCase().includes(search.toLowerCase()))));const shown=cards.slice(0,120);return title('WORDS THAT STICK','把單字，變成你的日常。','先理解詞組與例句，再透過主動回想，讓記憶留得更久。')+`<div class="vocab-banner"><div><span class="eyebrow">SPACED REPETITION</span><h2>今天，有 ${dueCards().length} 個單字等你複習。</h2><p>記住後依序安排 1、3、7、14、30 天複習；忘記就重新開始。已練習 ${Object.keys(state.cards).length} / ${BANK.vocabulary.length} 個。</p></div><div class="vocab-actions"><button class="button primary" data-action="flash">${icon('vocabulary')}翻卡練習</button><button class="button secondary" data-action="wordquiz">${icon('check')}單字測驗</button></div></div><div class="toolbar vocab-toolbar"><label class="search-field">${icon('search')}<input id="word-search" type="search" placeholder="搜尋英文、中文或詞組…" value="${esc(search)}" aria-label="搜尋單字"></label><label class="category-label">主題 <select id="word-filter">${['全部',...new Set(BANK.vocabulary.map(v=>v.tag))].map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="checkbox-label"><input type="checkbox" id="due-only" ${dueOnly?'checked':''}>只看到期單字</label></div><div class="section-heading"><h2>我的單字庫 <span class="inline-count">${cards.length}</span></h2><span class="quiet-label">每次練習最多 10 個，優先複習到期詞，再加入新字</span></div><div class="word-grid">${shown.map(v=>`<article class="panel word-card"><div><span class="tag">${v.tag}</span><button class="sound-button" data-speak="${v.id}" aria-label="播放 ${esc(v.word)} 發音">${icon('sound')}</button></div><h3 class="english">${esc(v.word)} <small>${v.pos}</small></h3><p>${v.meaning}</p><span class="phrase english">${esc(v.phrase)}</span><div class="word-status">${!state.cards[v.id]?'尚未練習':state.cards[v.id].due<=dateKey()?'今天複習':`下次複習 ${state.cards[v.id].due}`}</div></article>`).join('')||'<div class="empty-state">'+icon('search')+'<h2>沒有符合的單字</h2><p>試試其他關鍵字，或取消到期篩選。</p></div>'}</div>${cards.length>shown.length?`<p class="quiet-label center">目前顯示前 ${shown.length} 個，請用主題或關鍵字縮小範圍。</p>`:''}`}
function filteredDeck(){const list=BANK.vocabulary.filter(v=>(filter==='全部'||v.tag===filter)&&(!dueOnly||(state.cards[v.id]&&state.cards[v.id].due<=dateKey()))&&(!search||[v.word,v.meaning,v.phrase].some(t=>t.toLowerCase().includes(search.toLowerCase()))));return list.sort((a,b)=>{const rank=v=>!state.cards[v.id]?1:state.cards[v.id].due<=dateKey()?0:2;return rank(a)-rank(b)||(state.cards[a.id]?.due||'').localeCompare(state.cards[b.id]?.due||'')}).slice(0,10)}
function shuffle(arr){const out=arr.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function startDeck(mode){const cards=filteredDeck();if(!cards.length){toast('目前篩選沒有可練習的單字。');return}halt();deck={mode,cards,index:0,revealed:false,correct:0,choices:[],answer:null,finished:false};prepareCard();view='flash';render();window.scrollTo(0,0)}
function prepareCard(){const v=deck.cards[deck.index];deck.revealed=false;deck.answer=null;const segs=meaningSegs(v.meaning),ok=w=>w.id!==v.id&&!meaningSegs(w.meaning).some(x=>segs.includes(x)),same=BANK.vocabulary.filter(w=>ok(w)&&w.tag===v.tag),other=BANK.vocabulary.filter(w=>ok(w)&&w.tag!==v.tag);deck.choices=shuffle([v,...shuffle(same).slice(0,2),...shuffle(other)].slice(0,4))}
function recordCard(known){const v=deck.cards[deck.index],old=state.cards[v.id],stage=known?Math.min((old?.stage||0)+1,5):0;state.cards[v.id]={stage,due:shiftDay(dateKey(),known?[0,1,3,7,14,30][stage]:0)};if(!day().vocab.includes(v.id))day().vocab.push(v.id);save()}
function advanceCard(known){recordCard(known);if(known)deck.correct++;deck.index++;if(deck.index>=deck.cards.length){deck.finished=true;if(deck.mode==='quiz')state.history.push({date:dateKey(),kind:'vocabulary',id:'words-'+Date.now(),correct:deck.correct,total:deck.cards.length});save()}else prepareCard();render()}
function flash(){if(deck.finished)return `<div class="flash-wrap"><div class="panel deck-result"><span class="big-success">${icon('check')}</span><p class="eyebrow">A LITTLE PROGRESS</p><h1>又累積了 ${deck.cards.length} 個單字。</h1><p>${deck.mode==='quiz'?`本次答對 ${deck.correct} / ${deck.cards.length} 題`:`本次自評記住 ${deck.correct} 個，還需加強 ${deck.cards.length-deck.correct} 個`}，複習日期已安排好。</p><button class="button primary" data-nav="vocabulary">回到單字庫</button></div></div>`;const v=deck.cards[deck.index];return `<button class="back-link" data-nav="vocabulary">返回單字庫</button>`+title(deck.mode==='quiz'?'VOCABULARY QUIZ':'ACTIVE RECALL',deck.mode==='quiz'?'選出正確的意思。':'先回想，再翻開答案。',`第 ${deck.index+1} / ${deck.cards.length} 個單字`)+`<div class="deck-progress"><span style="width:${pct(deck.index,deck.cards.length)}%"></span></div><div class="flash-wrap"><article class="panel flash-card"><span class="tag">${v.tag}</span><button class="sound-button flash-sound" data-speak="${v.id}" aria-label="播放發音">${icon('sound')}</button><span class="eyebrow">${v.pos}</span><h2 class="english">${esc(v.word)}</h2>${deck.mode==='quiz'?`<div class="word-quiz-options">${deck.choices.map((w,i)=>`<button class="option ${deck.answer===i?'chosen':''} ${deck.answer!==null?(w.id===v.id?'correct':deck.answer===i?'incorrect':''):''}" data-word-answer="${i}" ${deck.answer!==null?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span>${w.meaning}</button>`).join('')}</div>${deck.answer!==null?`<div class="card-answer"><strong>${v.meaning}</strong><p class="english">${esc(v.phrase)}</p><p class="english example">${esc(v.example)}</p></div><button class="button primary" data-action="wordnext">下一個單字</button>`:''}`:deck.revealed?`<div class="card-answer"><h3>${v.meaning}</h3><p class="english">${esc(v.phrase)}</p><p class="english example">${esc(v.example)}</p></div><p class="recall-note">剛才有想出正確意思嗎？誠實評估，複習才會有效。</p><div class="recall-actions"><button class="button secondary" data-action="forgot">還沒記住</button><button class="button primary" data-action="known">我記住了 ${icon('check')}</button></div>`:`<p class="recall-hint">試著說出中文意思，或想一個使用情境。</p><button class="button primary" data-action="reveal">翻開答案</button>`}</article><p class="quiet-label center">理解一個詞組，比匆匆看過十個單字更有價值。</p></div>`}

/* ---------- 錯題筆記 ---------- */
function review(){const today=dateKey(),all=Object.entries(state.wrong).map(([key,w])=>({key,w,s:findSet(w.kind,w.id)})),due=all.filter(o=>o.w.due<=today).sort((a,b)=>a.w.due.localeCompare(b.w.due)),later=all.filter(o=>o.w.due>today).sort((a,b)=>a.w.due.localeCompare(b.w.due)),dueSets=[...new Map(due.map(o=>[o.w.kind+':'+o.w.id,o])).values()];
  const card=({key,w,s})=>{const q=s.questions[w.index];return `<article class="panel review-card"><div><span class="tag">${KINDS[w.kind].part} · ${esc(s.title)}</span> <span class="tag stage">${w.stage===0?'第 1 輪':'第 2 輪'} · ${w.due<=today?'今天可複習':'下次 '+w.due}</span>${w.misses>1?` <span class="tag warn">累計錯 ${w.misses} 次</span>`:''}<h2 class="english">${esc(qText(w.kind,s,w.index))}</h2>${causeChips(key)}<details><summary>查看線索與答案</summary><p>${esc(q.explain)}</p><strong class="english">${letters[q.answer]}. ${esc(q.options[q.answer])}</strong></details></div><button class="button ${w.due<=today?'primary':'secondary'}" data-start="${w.kind}:${s.id}">重做題組</button></article>`};
  return title('LEARN FROM EVERY MISTAKE','錯過的，變成下次的把握。','答錯的題目會在隔天到期；之後隔 3 天再答對一次，才算真正熟練並移出。')+`<div class="review-summary">${icon('review')}<span>今天可複習 <strong>${due.length}</strong> 題 · 排程中 <strong>${later.length}</strong> 題</span><span class="quiet-label">提前重做答對不計入進度，避免短期記憶造成假象</span></div>${dueSets.length?`<p class="recommend">${icon('spark')}今天要重做的題組：${dueSets.map(o=>`<button class="text-button" data-start="${o.w.kind}:${o.s.id}">${KINDS[o.w.kind].part} · ${esc(o.s.title)}</button>`).join('、')}</p>`:''}${all.length?`${due.length?`<div class="section-heading"><h2>今天到期</h2></div><div class="review-list">${due.map(card).join('')}</div>`:''}${later.length?`<div class="section-heading later"><h2>之後複習</h2><span class="quiet-label">依到期日排序</span></div><div class="review-list">${later.map(card).join('')}</div>`:''}`:`<div class="empty-state panel">${icon('leaf')}<h2>這裡，等著收藏你的進步。</h2><p>完成練習後，需加強的題目會自動加入。</p><button class="button primary" data-nav="reading">開始一組練習</button></div>`}`}

/* ---------- 學習紀錄 ---------- */
function stats(){const totalSeconds=Object.values(state.days).reduce((n,d)=>n+d.seconds,0),history=state.history.slice(-20).reverse(),causeCount={};state.causes.forEach(c=>causeCount[c.cause]=(causeCount[c.cause]||0)+1);const causeRows=Object.entries(causeCount).sort((a,b)=>b[1]-a[1]),causeTotal=state.causes.length,skillRows=Object.entries(state.skills).filter(([,v])=>v[1]>0).sort((a,b)=>pct(...a[1])-pct(...b[1]));
return title('YOUR PROGRESS','每一次練習，都算數。','看見自己的累積，也找到下一步需要加強的地方。')+`<section class="metric-grid"><article class="metric"><span class="metric-icon purple">${icon('clock')}</span><div><span>累積學習時間</span><strong>${Math.floor(totalSeconds/60)}<small> 分鐘</small></strong></div></article><article class="metric"><span class="metric-icon orange">${icon('check')}</span><div><span>完成測驗</span><strong>${state.history.length}<small> 次</small></strong></div></article><article class="metric"><span class="metric-icon green">${icon('vocabulary')}</span><div><span>已練習單字</span><strong>${Object.keys(state.cards).length}<small> 個</small></strong></div></article><article class="metric"><span class="metric-icon blue">${icon('spark')}</span><div><span>連續學習</span><strong>${streak()}<small> 天</small></strong></div></article></section><div class="lower-grid"><article class="panel"><div class="section-heading"><h2>近七天學習</h2><span class="quiet-label">分鐘 / 天</span></div>${weekChart()}</article><article class="panel skill-panel"><h2>各 Part 正確率</h2>${[...SET_KINDS.map(k=>[k,KINDS[k].part+' '+KINDS[k].label]),['vocabulary','單字測驗']].map(([kind,name])=>`<div class="skill-row"><span>${name}</span><div class="skill-track"><span style="width:${accuracy(kind)||0}%"></span></div><strong>${accuracy(kind)===null?'—':accuracy(kind)+'%'}</strong></div>`).join('')}<p class="quiet-label">包含練習、重做與模考；自評翻卡不計入。</p></article></div><div class="lower-grid"><article class="panel skill-panel"><h2>錯誤原因分布</h2>${causeRows.length?causeRows.map(([c,n])=>`<div class="skill-row"><span>${c}</span><div class="skill-track warm"><span style="width:${pct(n,causeTotal)}%"></span></div><strong>${n} 次</strong></div>`).join('')+`<p class="quiet-label">${causeRows[0][0]==='字彙不懂'?'字彙是主要障礙：每天把單字練習加到 20 個，並把錯題中的生字加入複習。':causeRows[0][0]==='文法觀念'?'文法是主要障礙：多做 Part 5，看解析時把文法規則寫成一句話。':causeRows[0][0]==='找不到依據'?'找依據是主要障礙：作答時先在文章中畫出答案句，再選選項。':causeRows[0][0]==='時間不夠'||causeRows[0][0]==='跟不上速度'?'速度是主要障礙：用模考練節奏，聽力搭配 1.2 倍速與聽寫。':causeRows[0][0]==='沒聽清楚'||causeRows[0][0]==='被相似音誤導'?'辨音是主要障礙：每組聽力做完後，用聽寫練習把聽不清楚的句子寫下來。':'同義改寫與粗心：交卷前重新比對選項和原文用字是否真的同義。'}</p>`:'<p class="empty-copy">答錯題目後標記原因，這裡會顯示你最常見的錯誤類型。</p>'}</article><article class="panel skill-panel"><h2>文法技能（Part 5 / 6）</h2>${skillRows.length?skillRows.map(([k,v])=>`<div class="skill-row"><span>${k}</span><div class="skill-track"><span style="width:${pct(...v)}%"></span></div><strong>${pct(...v)}%<small> ${v[0]}/${v[1]}</small></strong></div>`).join('')+'<p class="quiet-label">由低到高排序，最上面是最需要加強的觀念。</p>':'<p class="empty-copy">完成 Part 5 或 Part 6 後，這裡會依文法觀念分析正確率。</p>'}</article></div><article class="panel history-panel"><div class="section-heading"><h2>最近練習紀錄</h2><span class="quiet-label">最多顯示 20 筆</span></div>${history.length?`<div class="table-scroll"><table><thead><tr><th>日期</th><th>練習項目</th><th>答對 / 題數</th><th>正確率</th></tr></thead><tbody>${history.map(h=>`<tr><td>${esc(h.date)}</td><td>${h.kind==='vocabulary'?'單字測驗':`${KINDS[h.kind].part} · ${esc(findSet(h.kind,h.id)?.title||'練習')}${h.mode==='exam'?'（測驗）':''}`}</td><td>${h.correct} / ${h.total}</td><td><span class="score-pill">${pct(h.correct,h.total)}%</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-copy">尚無測驗紀錄。完成第一組練習，就從這裡看見進步。</p>'}</article><article class="panel settings-panel"><div><h2>我的學習設定</h2><p>紀錄只保存在目前的瀏覽器，不會自動同步到其他裝置。定期匯出備份，可在其他裝置匯入。</p><p class="quiet-label">時間僅計算頁面可見且最近有操作的時段；背景或閒置超過 2 分鐘暫停累積。</p></div><div class="settings-actions"><label>每日目標 <select id="goal-select">${[30,60,90,120].map(g=>`<option value="${g}" ${g===state.goal?'selected':''}>${g} 分鐘</option>`).join('')}</select></label><label>題組難度 <select id="level-select"><option value="" ${!state.level?'selected':''}>依診斷結果</option>${['基礎','進階'].map(l=>`<option ${state.level===l?'selected':''}>${l}</option>`).join('')}</select></label><button class="button secondary" data-action="export">${icon('download')}匯出紀錄</button><label class="button secondary import-label">匯入備份<input id="import-file" type="file" accept="application/json,.json"></label></div><p id="import-status" role="status"></p></article>`}

function render(){const oldAudio=$('#speech-audio');const pages={home,reading:()=>catalog('reading'),listening:()=>catalog('listening'),vocabulary:vocab,quiz,flash,review,stats,exam:examHub,examrun:examRun};$('#app').innerHTML=shell(pages[view]());const newAudio=$('#speech-audio');if(oldAudio&&newAudio&&oldAudio.getAttribute('src')===newAudio.getAttribute('src')){newAudio.replaceWith(oldAudio);$('#audio-rate').value=String(oldAudio.playbackRate)}else{if(oldAudio)oldAudio.pause();if(newAudio)newAudio.addEventListener('error',()=>{const error=$('#audio-error');if(error)error.textContent='音檔無法載入，請檢查連線後重播。';})}document.title=`${mainNames[view][0]} · TOEIC 700 練習室`}
function speak(id){const v=BANK.vocabulary.find(v=>v.id===id);if(!v)return;if(!hasSpeech()){toast('此瀏覽器不支援單字發音，請使用新版 Chrome、Edge 或 Safari。');return}stopSpeech();const u=new SpeechSynthesisUtterance(v.word+'. '+v.phrase);u.lang='en-US';u.rate=.85;const voices=englishVoices();u.voice=voices[0]||null;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('無法播放單字發音，請確認裝置已安裝英文語音。')};speechSynthesis.speak(u)}
function currentSet(){if(view==='quiz'&&run)return{kind:run.kind,s:findSet(run.kind,run.id)};if(view==='examrun'&&exam&&exam.idx>=0){const x=exam.sets[exam.idx];return{kind:x.kind,s:findSet(x.kind,x.id)}}return null}
function keepScroll(fn,selector){const y=window.scrollY;fn();render();if(selector)document.querySelector(selector)?.focus({preventScroll:true});window.scrollTo(0,y)}

document.addEventListener('click',e=>{lastActive=Date.now();
  const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();nav(navEl.dataset.nav);return}
  const startEl=e.target.closest('[data-start]');if(startEl){start(...startEl.dataset.start.split(':'));return}
  const filterEl=e.target.closest('[data-filter]');if(filterEl){filter=filterEl.dataset.filter;render();return}
  const partEl=e.target.closest('[data-part-filter]');if(partEl){partFilter=partEl.dataset.partFilter;render();return}
  const ans=e.target.closest('[data-answer]');if(ans&&run&&!run.submitted){const [i,j]=ans.dataset.answer.split(':').map(Number);keepScroll(()=>{run.answers[i]=j},`[data-answer="${i}:${j}"]`);return}
  const ex=e.target.closest('[data-exam-answer]');if(ex&&exam&&!exam.submitted){const [i,j]=ex.dataset.examAnswer.split(':').map(Number),x=exam.sets[exam.idx];keepScroll(()=>{exam.answers[`${x.kind}:${x.id}:${i}`]=j;exam.confirming=false},`[data-exam-answer="${i}:${j}"]`);return}
  const go=e.target.closest('[data-exam-go]');if(go&&exam){halt();exam.idx=Number(go.dataset.examGo);exam.confirming=false;render();window.scrollTo(0,0);return}
  const cause=e.target.closest('[data-cause]');if(cause){const [key,c]=cause.dataset.cause.split('|');keepScroll(()=>setCause(key,c));return}
  const voice=e.target.closest('[data-voice]');if(voice){halt();state.voice=voice.dataset.voice==='browser'?'browser':'file';save();render();return}
  const p2=e.target.closest('[data-p2play]');if(p2){const cur=currentSet();if(cur){const q=cur.s.questions[Number(p2.dataset.p2play)];if(speakQueue(part2Items(q)))p2.classList.add('speaking')}return}
  const snd=e.target.closest('[data-speak]');if(snd){speak(snd.dataset.speak);return}
  const wa=e.target.closest('[data-word-answer]');if(wa&&deck.answer===null){deck.answer=Number(wa.dataset.wordAnswer);render();return}
  const task=e.target.closest('[data-task]');if(task){if(task.dataset.task==='vocabulary'){filter='全部';search='';dueOnly=false;startDeck('flash')}else{const n=nextSet(task.dataset.task);start(n.kind,n.set.id)}return}
  const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
  switch(action){
    case'daily':{if(day().vocab.length<10){filter='全部';search='';dueOnly=false;startDeck('flash');break}const t=['grammar','reading','listening'].find(t=>!taskDone(t));if(t){const n=nextSet(t);start(n.kind,n.set.id)}else nav(dueWrong().length?'review':'exam');break}
    case'submit':submitQuiz();break;
    case'next':{const list=BANK[run.kind],i=list.findIndex(x=>x.id===run.id);start(run.kind,list[(i+1)%list.length].id);break}
    case'replay':{const a=$('#speech-audio');if(!a)break;a.currentTime=0;a.play().catch(()=>toast('音訊播放失敗，請點播放鍵再試一次。'));break}
    case'voice-play':{const cur=currentSet();if(cur&&speakQueue(parseTranscript(cur.s.transcript)))toast('開始播放雙聲道對話。');break}
    case'voice-stop':stopSpeech();break;
    case'dict-play':{const cur=currentSet();if(!cur||!dict)break;const lines=cur.kind==='listening'?parseTranscript(cur.s.transcript).map(x=>x.text):cur.s.questions.flatMap(q=>[q.q,q.options[q.answer]]);speakQueue([{speaker:'D',text:lines[dict.idx]}]);break}
    case'dict-check':{const cur=currentSet();if(!cur||!dict)break;const lines=cur.kind==='listening'?parseTranscript(cur.s.transcript).map(x=>x.text):cur.s.questions.flatMap(q=>[q.q,q.options[q.answer]]);dict.input=$('#dict-input')?.value||dict.input;if(!dict.input.trim()){toast('請先輸入聽到的句子。');break}dict.result=compareDictation(lines[dict.idx],dict.input);keepScroll(()=>{});break}
    case'exam-resume':if(exam){view='examrun';render();window.scrollTo(0,0)}break;
    case'diag-start':startExam('diagnostic');break;
    case'mock-mini':startExam('mock','mini');break;
    case'mock-full':startExam('mock','full');break;
    case'exam-prev':if(exam&&exam.idx>0){halt();exam.idx--;exam.confirming=false;render();window.scrollTo(0,0)}break;
    case'exam-next':if(exam&&exam.idx<exam.sets.length-1){halt();exam.idx++;exam.confirming=false;render();window.scrollTo(0,0)}break;
    case'exam-submit':{if(!exam||exam.submitted)break;const t=examTotals();if(t.answered<t.total&&!exam.confirming){exam.confirming=true;render();break}submitExam(false);break}
    case'flash':startDeck('flash');break;case'wordquiz':startDeck('quiz');break;case'reveal':deck.revealed=true;render();break;case'known':advanceCard(true);break;case'forgot':advanceCard(false);break;case'wordnext':advanceCard(deck.choices[deck.answer].id===deck.cards[deck.index].id);break;
    case'focus':if(focusRemaining<=0)focusRemaining=1500;focusOn=!focusOn;render();break;
    case'export':{save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`toeic700-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已匯出學習紀錄。');break}}
});
document.addEventListener('change',e=>{lastActive=Date.now();const id=e.target.id;
  if(id==='audio-rate'&&$('#speech-audio'))$('#speech-audio').playbackRate=Number(e.target.value);
  if(id==='speech-rate')speechRate=Number(e.target.value)||1;
  if(id==='show-text'){if(view==='quiz'&&run)run.showText=e.target.checked;if(view==='examrun'&&exam)exam.showText=e.target.checked;keepScroll(()=>{})}
  if(id==='dict-select'&&dict){dict.idx=Number(e.target.value);dict.input='';dict.result=null;keepScroll(()=>{})}
  if(id==='word-filter'){filter=e.target.value;render()}if(id==='due-only'){dueOnly=e.target.checked;render()}
  if(id==='goal-select'){state.goal=Number(e.target.value);save();render()}
  if(id==='level-select'){state.level=['基礎','進階'].includes(e.target.value)?e.target.value:(lastDiag()?bandOf(pct(lastDiag().correct,lastDiag().total)).level:null);save();render()}
  if(id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>5e6){toast('備份檔過大，請選擇 5 MB 以下的 JSON。');return}file.text().then(text=>{const imported=normalize(JSON.parse(text));if(!window.confirm('匯入會取代目前瀏覽器的學習紀錄。建議先匯出目前紀錄。確定匯入嗎？'))return;state=imported;save();render();toast('備份已匯入。')}).catch(()=>toast('備份檔格式有誤，現有紀錄未變更。'))}});
document.addEventListener('input',e=>{lastActive=Date.now();if(e.target.id==='dict-input'&&dict){dict.input=e.target.value;return}if(e.target.id==='word-search'){if(e.isComposing)return;search=e.target.value;const pos=e.target.selectionStart;render();const inp=$('#word-search');inp.focus();if(pos!==null)inp.setSelectionRange(pos,pos)}});
['pointerdown','keydown','scroll'].forEach(event=>document.addEventListener(event,()=>lastActive=Date.now(),{passive:true}));
let lastTick=Date.now();setInterval(()=>{const now=Date.now(),elapsed=Math.min(5,(now-lastTick)/1000);lastTick=now;const visible=document.visibilityState==='visible';if(visible&&now-lastActive<120000){day().seconds+=elapsed;timerTicks++;if(timerTicks%15===0)save()}if(visible&&exam&&!exam.submitted&&view==='examrun'){exam.elapsed+=elapsed;const el=$('#exam-timer');if(exam.limit&&exam.elapsed>=exam.limit){submitExam(true)}else if(el){el.innerHTML=icon('clock')+(exam.limit?'剩餘 '+fmtTime(exam.limit-exam.elapsed):'已用 '+fmtTime(exam.elapsed));el.classList.toggle('urgent',!!exam.limit&&exam.limit-exam.elapsed<120)}}if(focusOn&&visible){focusRemaining=Math.max(0,focusRemaining-elapsed);const label=$('#focus-label');if(label)label.textContent=`專注中 ${fmtTime(focusRemaining)}`;if(focusRemaining<=0){focusOn=false;toast('25 分鐘專注完成！休息一下，再繼續。')}}},1000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.visibilityState==='hidden')save()});window.addEventListener('pagehide',()=>{save();halt()});
render();
})();
